    +CMP16X addr_mode0, operand0, addr_mode1, operand1
    bcs _L_O_O_P_L_V_L_1_

  } else if condition = IS_GREATER_OR_EQUAL_THAN {
    +CMP16 addr_mode0, operand0, addr_mode1, operand1
