// Package prgfile reads programs from Commodore BASIC tokenized (PRG) files.
//
// Usage:
//
//	pr, err := prgfile.New(r)
//	...
//	for {
//	   line, err := pr.Line()
//	   if err == io.EOF {
//	      break
//	   } else if err != nil {
//	      log.Fatal("Failed: %v", err)
//	   }
//	   doSomethingWith(line)
//	}
package prgfile

import (
	"bufio"
	"fmt"
	"io"
	"strings"
)

/*
  File grammar:

    file  = org [lines]
    lines = line [lines]
    line  = eof
          | addr lnum 0*insn eol line
    org   = WORD
    eof   = \x00 \x00
    addr  = WORD
    lnum  = WORD
    insn  = 1*BYTE
    eol   = \x00
    WORD  = [2]BYTE ;; LSB first

  http://fileformats.archiveteam.org/wiki/Commodore_BASIC_tokenized_file
*/

const tokenBase = 128 // smallest byte value for a token

var spelling = []string{
	// offset = code - tokenBase
	"END", "FOR", "NEXT", "DATA", "INPUT#", "INPUT", "DIM", "READ", "LET",
	"GOTO", "RUN", "IF", "RESTORE", "GOSUB", "RETURN", "REM", "STOP", "ON",
	"WAIT", "LOAD", "SAVE", "VERIFY", "DEF", "POKE", "PRINT#", "PRINT", "CONT",
	"LIST", "CLR", "CMD", "SYS", "OPEN", "CLOSE", "GET", "NEW", "TAB(", "TO",
	"FN", "SPC(", "THEN", "NOT", "STEP", "+", "-", "*", "/", "^", "AND", "OR",
	">", "=", "<", "SGN", "INT", "ABS", "USR", "FRE", "POS", "SQR", "RND",
	"LOG", "EXP", "COS", "SIN", "TAN", "ATN", "PEEK", "LEN", "STR$", "VAL",
	"ASC", "CHR$", "LEFT$", "RIGHT$", "MID$", "GO",
}

func isToken(ch byte) (string, bool) {
	v := int(ch) - tokenBase
	if v >= 0 && v < len(spelling) {
		return spelling[v], true
	}
	return "", false
}

// A Reader parses a tokenized program and returns lines containing the decoded
// instructions.
type Reader struct {
	org      uint16 // origin address from the stream header
	nextAddr uint16 // base address of next line (0 at start)

	buf *bufio.Reader
	pos int
}

// word returns the value of the next 2 bytes of input as a little-endian
// unsigned value, and advances the offset.
func (r *Reader) word() (uint16, error) {
	var word [2]byte
	nr, err := io.ReadFull(r.buf, word[:])
	r.pos += nr
	if err != nil {
		return 0, err
	}
	return (uint16(word[1]) << 8) | uint16(word[0]), nil
}

// byte returns the next byte of input, and advances the offset.
func (r *Reader) byte() (byte, error) {
	b, err := r.buf.ReadByte()
	if err == nil {
		r.pos++
	}
	return b, err
}

// fail decorates an error message with location information.
func (r *Reader) fail(msg string, args ...any) error {
	return fmt.Errorf("offset %d: %s", r.pos, fmt.Sprintf(msg, args...))
}

// New constructs a *Reader that consumes input from r, which is expected to be
// positioned at the origin mark beginning a PRG file.
func New(r io.Reader) (*Reader, error) {
	rd := &Reader{buf: bufio.NewReader(r)}
	org, err := rd.word()
	if err != nil {
		return nil, rd.fail("reading origin: %v", err)
	}
	rd.org = org
	rd.nextAddr = org
	return rd, nil
}

// A Line represents a single program line containing instructions.
type Line struct {
	N    uint16   // line number
	Addr uint16   // memory address of first instruction
	Insn []string // instructions on this line
}

// An insn represents a single BASIC instruction.
type insn []string

// isWord reports whether ch should be considered part of a "word", which
// notionally is something written with letters and digits, but for our
// purposes includes quotation marks so string literals are units.
func isWord(ch byte) bool {
	return ch == '"' || // honorary
		ch >= 'A' && ch <= 'Z' ||
		ch >= 'a' && ch <= 'z' ||
		ch >= '0' && ch <= '9'
}

func endsWord(s string) bool   { return s != "" && isWord(s[len(s)-1]) }
func startsWord(s string) bool { return s != "" && isWord(s[0]) }

// String renders the instruction with suitable whitespace inserted or removed
// between consecutive tokens.
func (in insn) String() string {
	var str strings.Builder
	ew := false
	for _, w := range in {
		if ew && startsWord(w) {
			str.WriteByte(' ')
		}
		str.WriteString(w)
		ew = endsWord(w)
	}
	return str.String()
}

// Origin returns the origin address for the input.
func (r *Reader) Origin() uint16 { return r.org }

// Pos returns the current byte offset in the input.
func (r *Reader) Pos() int { return r.pos }

// Line parses and returns the next line from the input.
// It returns nil, io.EOF when the end of instruction marker is reached.
func (r *Reader) Line() (*Line, error) {
	addr := r.nextAddr

	// Read the next line address from the line prefix.
	next, err := r.word()
	if err != nil {
		return nil, r.fail("reading next address: %v", err)
	}
	r.nextAddr = next
	if next == 0 {
		return nil, io.EOF
	}

	// Read the current line number.
	lnum, err := r.word()
	if err != nil {
		return nil, r.fail("reading line number: %v", err)
	}

	// Collect instructions.
	var insns []string      // instructions on current line
	var words insn          // words in current instruction
	var cur strings.Builder // current word
	quoted := false         // currently inside quotes

	// Push the current word onto the instruction.
	push := func() {
		if cur.Len() != 0 {
			words = append(words, cur.String())
			cur.Reset()
		}
	}

	// Push the current instruction onto the line.
	emit := func() {
		push()
		if len(words) != 0 {
			insns = append(insns, words.String())
			words = nil
		}
	}

	for {
		ch, err := r.byte()
		if err != nil {
			return nil, r.fail("reading instruction: %v", err)
		} else if ch == 0 {
			emit()
			break // end of line
		}

		// An unquoted token is expanded to its spelling. This delimits any
		// previous in-progress word.
		if s, ok := isToken(ch); ok && !quoted {
			push()
			words = append(words, s)
			continue
		}

		// Double quotes toggle string literals, inside which tokens are not
		// expanded (though in principle they should not occur there anyway).
		if ch == '"' {
			quoted = !quoted
		} else if ch == ':' && !quoted {
			// An un-quoted colon is treated as its own token, even though it does
			// not appear in the token grammar. This allows instructions to be
			// distinguished later.
			emit()
			continue
		}
		cur.WriteByte(ch)
	}

	return &Line{
		N:    lnum,
		Addr: addr,
		Insn: insns,
	}, nil
}

mikolas-hunks-internal-hunk-parser-go.text:
// Package hunk parses AmigaDOS LoadSeg() multi-hunk executables (HUNK_HEADER 0x03F3).
//
// It extracts per-hunk memory attributes (Public, Chip, Fast), advertised allocation
// sizes, initialized payloads (HUNK_CODE, HUNK_DATA, HUNK_BSS), 32-bit relocation
// tables (HUNK_RELOC32, HUNK_DREL32, HUNK_RELOC32SHORT), and symbol tables
// (HUNK_SYMBOL), and computes disjoint synthetic base addresses so all hunks can share
// a unified 32-bit analysis address space.
package hunk

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"fmt"
)

const (
	HunkName         uint32 = 0x03E8
	HunkCode         uint32 = 0x03E9
	HunkData         uint32 = 0x03EA
	HunkBss          uint32 = 0x03EB
	HunkReloc32      uint32 = 0x03EC
	HunkReloc16      uint32 = 0x03ED
	HunkReloc8       uint32 = 0x03EE
	HunkExt          uint32 = 0x03EF
	HunkSymbol       uint32 = 0x03F0
	HunkDebug        uint32 = 0x03F1
	HunkEnd          uint32 = 0x03F2
	HunkHeader       uint32 = 0x03F3
	HunkDRel32       uint32 = 0x03F7
	HunkDRel16       uint32 = 0x03F8
	HunkDRel8        uint32 = 0x03F9
	HunkReloc32Short uint32 = 0x03FC
	HunkRelReloc32   uint32 = 0x03FD

	HunkSizeMask uint32 = 0x3FFFFFFF
	MemfChipFlag uint32 = 0x40000000
	MemfFastFlag uint32 = 0x80000000
)

type HunkType string

const (
	HunkTypeCode HunkType = "Code"
	HunkTypeData HunkType = "Data"
	HunkTypeBss  HunkType = "Bss"
)

func (h HunkType) ToVasmType() string {
	switch h {
	case HunkTypeData:
		return "DATA"
	case HunkTypeBss:
		return "BSS"
	default:
		return "CODE"
	}
}

func (h *HunkType) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	switch HunkType(s) {
	case "", HunkTypeCode:
		*h = HunkTypeCode
	case HunkTypeData:
		*h = HunkTypeData
	case HunkTypeBss:
		*h = HunkTypeBss
	default:
		return fmt.Errorf("unknown HunkType %q", s)
	}
	return nil
}

type MemoryType string

const (
	MemoryPublic MemoryType = "Public"
	MemoryChip   MemoryType = "Chip"
	MemoryFast   MemoryType = "Fast"
)

func MemoryTypeFromRaw(raw uint32) MemoryType {
	if (raw & MemfChipFlag) != 0 {
		return MemoryChip
	}
	if (raw & MemfFastFlag) != 0 {
		return MemoryFast
	}
	return MemoryPublic
}

func (m MemoryType) ToVasmAttr() string {
	switch m {
	case MemoryChip:
		return ",CHIP"
	case MemoryFast:
		return ",FAST"
	default:
		return ""
	}
}

func (m *MemoryType) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	switch MemoryType(s) {
	case "", MemoryPublic:
		*m = MemoryPublic
	case MemoryChip:
		*m = MemoryChip
	case MemoryFast:
		*m = MemoryFast
	default:
		return fmt.Errorf("unknown MemoryType %q", s)
	}
	return nil
}

type RelocationBlock struct {
	TargetHunk int
	Offsets    []uint32
}

type SymbolEntry struct {
	Name   string
	Offset uint32
}

// ParsedHunk holds the parsed contents and metadata of a single hunk in an AmigaDOS executable.
//
// AllocSize is the full runtime allocation in bytes from HUNK_HEADER (or the hunk body tag when
// the header size is 0), whereas FileDataLen is the on-disk byte length of the HUNK_CODE or
// HUNK_DATA payload before any zero-extended BSS tail.
type ParsedHunk struct {
	Index       int
	HunkType    HunkType
	MemoryType  MemoryType
	AllocSize   uint32
	FileDataLen int
	Data        []byte
	Reloc32     []RelocationBlock
	Symbols     []SymbolEntry
}

// ParsedHunkFile represents a complete parsed AmigaDOS multi-hunk executable.
type ParsedHunkFile struct {
	TableSize uint32
	FirstHunk int
	LastHunk  int
	Hunks     []ParsedHunk
}

// CalculateSyntheticBases assigns a deterministic, non-overlapping synthetic base address
// to each hunk in sequential order. Even zero-length hunks advance the next base by at
// least 4 bytes so that every hunk has a distinct base address in the shared address space.
func (f *ParsedHunkFile) CalculateSyntheticBases() []uint32 {
	bases := make([]uint32, 0, len(f.Hunks))
	var currentBase uint32
	for _, h := range f.Hunks {
		bases = append(bases, currentBase)
		step := h.AllocSize
		if step < 4 {
			step = 4
		}
		currentBase += step
	}
	return bases
}

func (f *ParsedHunkFile) TotalRelocations() int {
	total := 0
	for _, h := range f.Hunks {
		for _, r := range h.Reloc32 {
			total += len(r.Offsets)
		}
	}
	return total
}

type hunkReader struct {
	data []byte
	pos  int
}

func (r *hunkReader) remaining() int {
	if r.pos >= len(r.data) {
		return 0
	}
	return len(r.data) - r.pos
}

func (r *hunkReader) readU32() (uint32, error) {
	if r.remaining() < 4 {
		return 0, fmt.Errorf("unexpected EOF reading u32 at offset 0x%X (total size: 0x%X)", r.pos, len(r.data))
	}
	v := binary.BigEndian.Uint32(r.data[r.pos : r.pos+4])
	r.pos += 4
	return v, nil
}

func (r *hunkReader) readU16() (uint16, error) {
	if r.remaining() < 2 {
		return 0, fmt.Errorf("unexpected EOF reading u16 at offset 0x%X (total size: 0x%X)", r.pos, len(r.data))
	}
	v := binary.BigEndian.Uint16(r.data[r.pos : r.pos+2])
	r.pos += 2
	return v, nil
}

func (r *hunkReader) readBytes(length int) ([]byte, error) {
	if r.remaining() < length {
		return nil, fmt.Errorf("unexpected EOF reading %d bytes at offset 0x%X (total size: 0x%X)", length, r.pos, len(r.data))
	}
	slice := r.data[r.pos : r.pos+length]
	r.pos += length
	return slice, nil
}

func (r *hunkReader) alignWord() {
	r.pos = (r.pos + 3) & ^3
}

func (r *hunkReader) skip(length int) error {
	if r.remaining() < length {
		return fmt.Errorf("unexpected EOF skipping %d bytes at offset 0x%X (total size: 0x%X)", length, r.pos, len(r.data))
	}
	r.pos += length
	return nil
}

// ParseHunkFile parses an AmigaDOS HUNK_HEADER executable image into its constituent hunks.
//
// Key format subtleties handled during parsing:
//   - Upper bits 30 and 31 on hunk size/tag longwords encode MEMF_CHIP and MEMF_FAST;
//     the low 30 bits (HunkSizeMask) give the longword count or tag ID.
//   - HUNK_DREL32 (0x03F7) and HUNK_RELOC32SHORT (0x03FC) pack count, target hunk, and
//     relocation offsets as 16-bit big-endian words, padded to a 32-bit longword boundary
//     after the terminating zero count word.
//   - Linkers may emit HUNK_CODE or HUNK_DATA blocks whose on-disk payload is shorter than
//     the HUNK_HEADER allocation size; ParseHunkFile zero-pads Data up to AllocSize for
//     in-bounds analysis while preserving the original FileDataLen so the emitter can emit
//     `dx.l`/`dx.b` for the uninitialized tail.
func ParseHunkFile(data []byte) (*ParsedHunkFile, error) {
	reader := &hunkReader{data: data}
	headerMagic, err := reader.readU32()
	if err != nil {
		return nil, fmt.Errorf("failed to read header magic: %w", err)
	}
	if (headerMagic & HunkSizeMask) != HunkHeader {
		return nil, fmt.Errorf("invalid hunk magic: expected 0x%04X, found 0x%04X", HunkHeader, headerMagic)
	}

	// Resident library names string table (if any)
	for {
		strLen, err := reader.readU32()
		if err != nil {
			return nil, fmt.Errorf("failed to read resident string length: %w", err)
		}
		if strLen == 0 {
			break
		}
		if err := reader.skip(int(strLen) * 4); err != nil {
			return nil, err
		}
	}

	tableSize, err := reader.readU32()
	if err != nil {
		return nil, fmt.Errorf("failed to read table size: %w", err)
	}
	firstU32, err := reader.readU32()
	if err != nil {
		return nil, fmt.Errorf("failed to read first hunk index: %w", err)
	}
	lastU32, err := reader.readU32()
	if err != nil {
		return nil, fmt.Errorf("failed to read last hunk index: %w", err)
	}
	firstHunk := int(firstU32)
	lastHunk := int(lastU32)
	if lastHunk < firstHunk {
		return nil, fmt.Errorf("invalid hunk range in header: first=%d, last=%d", firstHunk, lastHunk)
	}
	numHunks := lastHunk - firstHunk + 1

	type hunkHeaderDef struct {
		allocSize  uint32
		memoryType MemoryType
	}
	headerDefs := make([]hunkHeaderDef, 0, numHunks)
	for i := 0; i < numHunks; i++ {
		raw, err := reader.readU32()
		if err != nil {
			return nil, fmt.Errorf("failed to read header size for hunk %d: %w", firstHunk+i, err)
		}
		headerDefs = append(headerDefs, hunkHeaderDef{
			allocSize:  (raw & HunkSizeMask) * 4,
			memoryType: MemoryTypeFromRaw(raw),
		})
	}

	parsedHunks := make([]ParsedHunk, 0, numHunks)
	for hunkIdx, hDef := range headerDefs {
		hunkType := HunkTypeCode
		memoryType := hDef.memoryType
		allocSize := hDef.allocSize
		fileDataLen := 0
		var hunkData []byte
		var reloc32 []RelocationBlock
		var symbols []SymbolEntry

		for reader.remaining() > 0 {
			tagRaw, err := reader.readU32()
			if err != nil {
				return nil, fmt.Errorf("failed to read tag for hunk %d: %w", firstHunk+hunkIdx, err)
			}
			tagMem := MemoryTypeFromRaw(tagRaw)
			if tagMem != MemoryPublic && memoryType == MemoryPublic {
				memoryType = tagMem
			}
			tag := tagRaw & HunkSizeMask

			switch tag {
			case HunkName:
				slen, err := reader.readU32()
				if err != nil {
					return nil, err
				}
				if err := reader.skip(int(slen) * 4); err != nil {
					return nil, err
				}
			case HunkCode:
				hunkType = HunkTypeCode
				numLongsRaw, err := reader.readU32()
				if err != nil {
					return nil, err
				}
				byteLen := int(numLongsRaw&HunkSizeMask) * 4
				b, err := reader.readBytes(byteLen)
				if err != nil {
					return nil, err
				}
				hunkData = append([]byte(nil), b...)
				fileDataLen = byteLen
				if allocSize == 0 {
					allocSize = uint32(byteLen)
				}
			case HunkData:
				hunkType = HunkTypeData
				numLongsRaw, err := reader.readU32()
				if err != nil {
					return nil, err
				}
				byteLen := int(numLongsRaw&HunkSizeMask) * 4
				b, err := reader.readBytes(byteLen)
				if err != nil {
					return nil, err
				}
				hunkData = append([]byte(nil), b...)
				fileDataLen = byteLen
				if allocSize == 0 {
					allocSize = uint32(byteLen)
				}
			case HunkBss:
				hunkType = HunkTypeBss
				numLongsRaw, err := reader.readU32()
				if err != nil {
					return nil, err
				}
				byteLen := (numLongsRaw & HunkSizeMask) * 4
				if allocSize == 0 {
					allocSize = byteLen
				}
				fileDataLen = 0
				hunkData = nil
			case HunkReloc32:
				for {
					count, err := reader.readU32()
					if err != nil {
						return nil, err
					}
					if count == 0 {
						break
					}
					targetHunk, err := reader.readU32()
					if err != nil {
						return nil, err
					}
					offsets := make([]uint32, 0, count)
					for i := uint32(0); i < count; i++ {
						off, err := reader.readU32()
						if err != nil {
							return nil, err
						}
						offsets = append(offsets, off)
					}
					reloc32 = append(reloc32, RelocationBlock{
						TargetHunk: int(targetHunk),
						Offsets:    offsets,
					})
				}
			case HunkDRel32, HunkReloc32Short:
				for {
					count, err := reader.readU16()
					if err != nil {
						return nil, err
					}
					if count == 0 {
						break
					}
					targetHunk, err := reader.readU16()
					if err != nil {
						return nil, err
					}
					offsets := make([]uint32, 0, count)
					for i := uint16(0); i < count; i++ {
						off, err := reader.readU16()
						if err != nil {
							return nil, err
						}
						offsets = append(offsets, uint32(off))
					}
					reloc32 = append(reloc32, RelocationBlock{
						TargetHunk: int(targetHunk),
						Offsets:    offsets,
					})
				}
				reader.alignWord()
			case HunkSymbol:
				for {
					slen, err := reader.readU32()
					if err != nil {
						return nil, err
					}
					if slen == 0 {
						break
					}
					nameBytes, err := reader.readBytes(int(slen) * 4)
					if err != nil {
						return nil, err
					}
					end := bytes.IndexByte(nameBytes, 0)
					if end < 0 {
						end = len(nameBytes)
					}
					name := string(nameBytes[:end])
					sval, err := reader.readU32()
					if err != nil {
						return nil, err
					}
					if name != "" {
						symbols = append(symbols, SymbolEntry{Name: name, Offset: sval})
					}
				}
			case HunkDebug:
				dlen, err := reader.readU32()
				if err != nil {
					return nil, err
				}
				if err := reader.skip(int(dlen) * 4); err != nil {
					return nil, err
				}
			case HunkEnd:
				goto nextHunk
			default:
				return nil, fmt.Errorf("unsupported or unrecognized hunk tag 0x%04X at offset 0x%X in hunk %d", tag, reader.pos-4, firstHunk+hunkIdx)
			}
		}
	nextHunk:
		if int(allocSize) > len(hunkData) && hunkType != HunkTypeBss {
			padded := make([]byte, int(allocSize))
			copy(padded, hunkData)
			hunkData = padded
		}

		parsedHunks = append(parsedHunks, ParsedHunk{
			Index:       firstHunk + hunkIdx,
			HunkType:    hunkType,
			MemoryType:  memoryType,
			AllocSize:   allocSize,
			FileDataLen: fileDataLen,
			Data:        hunkData,
			Reloc32:     reloc32,
			Symbols:     symbols,
		})
	}

	return &ParsedHunkFile{
		TableSize: tableSize,
		FirstHunk: firstHunk,
		LastHunk:  lastHunk,
		Hunks:     parsedHunks,
	}, nil
}

digarok-iigs-programmers-workshop-asm-om.text:
package asm

import "encoding/binary"

// Segment is one assembled OMF segment: header parameters plus the finished
// record stream (which already ends with the END record).
type Segment struct {
	Name       string
	LoadName   string
	Org        int64
	TempOrg    int64
	HasTempOrg bool
	Kind       uint16 // OMF KIND: $4000 private code, $4001 private data
	KindSet    bool   // Kind is explicit, so a zero value means KIND $0000
	Skip       bool   // KIND SKIP bit ($0200), set by the sticky PROC SKIP mode
	Attrs      uint16 // KIND attribute bits from the sticky SegAttr mode
	Align      int64  // PROC ALIGN n (segment alignment), 0 = none
	Length     int64
	Records    []byte
}

// Object is a finished assembly: one segment per PROC.
type Object struct {
	Segments []Segment
}

// WriteOMF emits the object as an OMF v2 object file, matching the original
// AsmIIGS output byte-for-byte (header layout, KIND=$4000 private code,
// LOADNAME "main") as established against the oracle.
func (o *Object) WriteOMF() []byte {
	var out []byte
	for i := range o.Segments {
		out = append(out, o.Segments[i].writeSeg(i+1)...)
	}
	return out
}

func (s *Segment) writeSeg(segNum int) []byte {
	le := binary.LittleEndian
	name := s.Name
	if len(name) > 255 {
		name = name[:255]
	}
	dispName := 0x2C
	if s.HasTempOrg {
		dispName = 0x30 // OMF v2.1: TEMPORG occupies $2C..$2F
	}
	dispData := dispName + 10 + 1 + len(name)
	byteCnt := dispData + len(s.Records)

	hdr := make([]byte, dispData)
	le.PutUint32(hdr[0x00:], uint32(byteCnt))  // BYTECNT
	le.PutUint32(hdr[0x04:], 0)                // RESSPC
	le.PutUint32(hdr[0x08:], uint32(s.Length)) // LENGTH
	hdr[0x0D] = 0                              // LABLEN (pstrings)
	hdr[0x0E] = 4                              // NUMLEN
	hdr[0x0F] = 2                              // VERSION
	kind := s.Kind
	if kind == 0 && !s.KindSet {
		kind = 0x4000 // private code
	}
	if s.Skip {
		kind |= 0x0200
	}
	kind |= s.Attrs
	// The low five bits of KIND are the segment type; data ($01) and
	// DP/stack ($12) segments carry BANKSIZE 0 whatever their attribute
	// bits say (oracle-verified for $4001, the exported $0001, and $4012).
	if t := kind & 0x1F; t != 0x01 && t != 0x12 {
		le.PutUint32(hdr[0x10:], 0x10000) // BANKSIZE
	}
