"""Build full Macintosh device images using machfs and a known driver donor.

No physical drives are opened. Images are created exclusively (never replaced).
The driver donor is read-only. The entire device image is 500 MiB by default;
the small partition map and SCSI driver consume part of that capacity.
"""
import argparse, copy, hashlib, json, pathlib, struct, sys
from .io_checks import check_new_output
from .hfs_image import HFSImage, u16, u32, p32, extents,validate_btree

DEFAULT_BYTES=500*1024*1024

def file_sha256(path):
    h=hashlib.sha256()
    with open(path,'rb') as fp:
        for b in iter(lambda:fp.read(1024*1024),b''): h.update(b)
    return h.hexdigest()

def read_volume(path):
    from machfs import Volume
    source=HFSImage(path)
    raw=source.read_at(source.offset,source.volume_size)
    original=source.report(True); source.close()
    volume=Volume(); volume.read(raw)
    volume.name=original['volume']
    return volume, original

def make_device_prefix(donor_path, total_bytes, name):
    """Clone the donor's DDR/map/driver, with newly sized HFS partition.

    Only one original HFS partition is supported and all driver partitions must
    precede it. No driver binary bytes are changed. Unused map entries are zeroed.
    """
    donor=HFSImage(donor_path)
    if not donor.partitions or donor.read_at(0,2)!=b'ER':
        donor.close(); raise ValueError('Driver donor must be a full Macintosh device image')
    if u16(donor.read_at(0,512),2)!=512:
        donor.close(); raise ValueError('Only 512 byte block device images supported')
    hfs=next(x for x in donor.partitions if x['type']=='Apple_HFS')
    map_parts=[x for x in donor.partitions if x['type']=='Apple_partition_map']
    driver_parts=[x for x in donor.partitions if x['type'] in ('Apple_Driver','Apple_Driver43')]
    if len(map_parts)!=1 or not driver_parts:
        donor.close(); raise ValueError('Missing supported map or Macintosh SCSI driver')
    keep=[map_parts[0],*driver_parts,hfs]
    start=hfs['start']*512
    if total_bytes%512 or total_bytes<=start+400*1024:
        donor.close(); raise ValueError('Invalid requested device size')
    for p in keep[:-1]:
        if (p['start']+p['blocks'])*512>start:
            donor.close(); raise ValueError('Non-HFS partition overlaps volume')
    prefix=bytearray(donor.read_at(0,start))
    old_entries=[bytearray(donor.read_at(p['index']*512,512)) for p in keep]
    driver_count=u16(prefix,16)
    if not 1<=driver_count<=61:
        donor.close(); raise ValueError('Invalid driver descriptor count')
    for i in range(driver_count):
        driver_start=u32(prefix,18+8*i); driver_blocks=u16(prefix,22+8*i)
        if driver_start*512>=start or (driver_start+driver_blocks)*512>start:
            donor.close(); raise ValueError('Driver descriptor outside cloned prefix')
    p32(prefix,4,total_bytes//512)
    # Preserve the map partition's declared reservation, including unused slots.
    pm=map_parts[0]
    for offset in range(pm['start']*512,(pm['start']+pm['blocks'])*512,512):
        prefix[offset:offset+512]=bytes(512)
    for i,entry in enumerate(old_entries):
        p32(entry,4,len(keep))
        if i==len(old_entries)-1:
            blocks=(total_bytes-start)//512
            p32(entry,12,blocks)
            p32(entry,80,0)
            p32(entry,84,blocks)
            encoded=name.encode('mac_roman')
            if len(encoded)>31: raise ValueError('Partition name too long')
            entry[16:48]=encoded.ljust(32,b'\0')
        prefix[(i+1)*512:(i+2)*512]=entry
    details={'donor':str(donor_path),'donor_sha256':file_sha256(donor_path),
        'prefix_bytes':start,'device_bytes':total_bytes,'volume_bytes':total_bytes-start,
        'driver_partitions':driver_parts,'driver_descriptors':driver_count,
        'driver_bytes_sha256':[
            hashlib.sha256(donor.read_at(x['start']*512,x['blocks']*512)).hexdigest()
            for x in driver_parts]}
    donor.close()
    return bytes(prefix),details

def object_manifest(volume):
    from machfs import File
    return {':'.join(path):{
            'type':obj.type.decode('mac_roman'),'creator':obj.creator.decode('mac_roman'),
            'data_size':len(obj.data),'resource_size':len(obj.rsrc),
            'data_sha256':hashlib.sha256(obj.data).hexdigest(),
            'resource_sha256':hashlib.sha256(obj.rsrc).hexdigest(),
            'alias':getattr(obj,'aliastarget',None) is not None}
        for path,obj in volume.iter_paths() if isinstance(obj,File)}

def write_device_image(volume, donor_path, destination, bootable, total_bytes=DEFAULT_BYTES, desktopdb=None):
    """Serialize a private copy with fresh Finder icon registrations.

    Desktop caches contain catalogue-specific registrations and cannot be
    carried into a newly serialized volume. A copied HasBeenInited bit would
    refer Finder to those discarded registrations, so clear only that bit.
    The caller's objects, bundle flags and file forks remain unchanged.
    """
    from machfs import File
    destination=check_new_output(destination)
    if destination.exists(): raise FileExistsError(destination)
    prefix,details=make_device_prefix(donor_path,total_bytes,volume.name)
    working_volume=copy.deepcopy(volume)
    omitted_caches=[]
    for name in ('Desktop','Desktop DB','Desktop DF'):
        if name in working_volume:
            working_volume.pop(name);omitted_caches.append(name)
    registration_resets=[]
    for path,obj in working_volume.iter_paths():
        if isinstance(obj,File) and obj.flags&0x0100:
            original_flags=obj.flags;obj.flags&=~0x0100
            registration_resets.append({'path':':'.join(path),
                'before':original_flags,'after':obj.flags})
    expected=object_manifest(working_volume)
    # sparse=True limits memory use; the output has the complete logical length.
    if desktopdb is None:desktopdb=False
    left,unused,right=working_volume.write(size=details['volume_bytes'],align=512,
        desktopdb=desktopdb,bootable=bootable,sparse=True)
    if not bootable:
        # machfs 1.3 detects a System/Finder pair regardless of its bootable
        # argument. Data archives can contain old installer/support Systems;
        # explicitly leave them unblessed without changing any file forks.
        left=bytearray(left);right=bytearray(right)
        left[:1024]=bytes(1024)
        left[1024+92:1024+124]=bytes(32)
        right[92:124]=bytes(32)
    destination.parent.mkdir(parents=True,exist_ok=True)
    with destination.open('xb') as fp:
        fp.write(prefix); fp.write(left); fp.seek(unused,1); fp.write(right)
        fp.flush()
    if destination.stat().st_size!=total_bytes: raise ValueError('Unexpected final image size')
    result=validate_device(destination,details,expected,bootable)
    result['sha256']=file_sha256(destination)
    result['build']={'library':'machfs','bootable':bootable,'desktopdb':desktopdb,
        'alignment_bytes':512,'total_bytes':total_bytes,'empty_free_space_is_zero':True,
        'caller_volume_serialized_as_private_copy':True,
        'omitted_source_desktop_caches':omitted_caches,
        'finder_registration_policy':'Clear only HasBeenInited (0x0100), preserving HasBundle and every other Finder flag',
        'finder_registration_resets':registration_resets}
    return result

def wrap_raw_volume(source_path,donor_path,destination,name,bootable,total_bytes=DEFAULT_BYTES):
    """Wrap an already formatted HFS volume of exactly the required net size."""
    prefix,details=make_device_prefix(donor_path,total_bytes,name)
    source=HFSImage(source_path)
    if source.partitions or source.diskcopy or source.volume_size!=details['volume_bytes']:
        source.close(); raise ValueError('Input must be raw HFS volume of '+str(details['volume_bytes'])+' bytes')
    if source.volume_name!=name:
        source.close(); raise ValueError('Raw volume name does not match requested name')
    source_report=source.report(True); source.close()
    expected={':'.join(f['path'].split(':')[1:]):{
        **{k:f[k] for k in ['type','creator','data_size','resource_size','data_sha256','resource_sha256']},
        'alias':False} for f in source_report['files']}
    destination=check_new_output(destination)
    destination.parent.mkdir(parents=True,exist_ok=True)
    with destination.open('xb') as out,open(source_path,'rb') as source_fp:
        out.write(prefix)
        for chunk in iter(lambda:source_fp.read(1024*1024),b''): out.write(chunk)
    if destination.stat().st_size!=total_bytes: raise ValueError('Unexpected final size')
    result=validate_device(destination,details,expected,bootable)
    result['sha256']=file_sha256(destination)
    result['build']={'method':'unchanged raw HFS volume plus cloned/ resized APM and driver prefix',
        'raw_volume_path':str(source_path),'raw_volume_sha256':file_sha256(source_path)}
    return result

def validate_device(path,donor_details=None,expected_files=None,bootable=False):
    image=HFSImage(path)
    result=image.report(True)
    checks=[]
    if not result['partitions']: raise ValueError('No Apple partition map')
    if u32(image.read_at(0,512),4)*512!=image.size: raise ValueError('DDR device length mismatch')
    if image.read_at(image.offset+image.volume_size-1024,512)!=image.mdb:
        raise ValueError('Alternate MDB does not match primary')
    checks.extend(['APM and DDR bounds','classic HFS signature','alternate MDB matches'])
    trees={}
    for label,fid,exoffset,sizeoffset in [('Extents overflow',3,134,130),('Catalog',4,150,146)]:
        tree=image.read_fork(fid,0,extents(image.mdb,exoffset),u32(image.mdb,sizeoffset))
        trees[label]=validate_btree(tree)
    result['btrees']=trees
    checks.append('B-tree index routing, node allocation maps and leaf links')
    owners={}
    def claim(ex,label):
        for start,count in ex:
            for block in range(start,start+count):
                if block in owners: raise ValueError('Overlapping allocation extents: '+label+' / '+owners[block])
                if block>=image.block_count: raise ValueError('Allocation outside volume')
                owners[block]=label
    claim(image.fork_extents(3,0,extents(image.mdb,134),u32(image.mdb,130)),'Extents overflow')
    claim(image.fork_extents(4,0,extents(image.mdb,150),u32(image.mdb,146)),'Catalog')
    for f in image.files:
        for fork,offset,size in [(0,74,f['data_size']),(255,86,f['resource_size'])]:
            claim(image.fork_extents(f['id'],fork,extents(f['record'],offset),size),image.item_path(f)+str(fork))
    bitmap=image.read_at(image.offset+u16(image.mdb,14)*512,(image.block_count+7)//8)
    allocated={i for i in range(image.block_count) if bitmap[i//8]&(0x80>>(i%8))}
    if allocated!=set(owners): raise ValueError('Allocation bitmap and extents disagree')
    if image.block_count-len(allocated)!=u16(image.mdb,34): raise ValueError('Free block count incorrect')
    if len(image.files)!=u32(image.mdb,84): raise ValueError('MDB file count mismatch')
    if len(image.folders)-1!=u32(image.mdb,88): raise ValueError('MDB directory count mismatch')
    for folder_id,folder in image.folders.items():
        children=sum(x['kind'] in (0x100,0x200) and x['parent']==folder_id for x in image.records)
        if children!=u16(folder['record'],4): raise ValueError('Directory valence mismatch')
    checks.extend(['both forks readable','allocation extents disjoint','allocation bitmap exact',
        'free block count correct','file/directory counts and folder valences correct'])
    if donor_details:
        hashes=[]
        for driver in [x for x in image.partitions if x['type'] in ('Apple_Driver','Apple_Driver43')]:
            hashes.append(hashlib.sha256(image.read_at(driver['start']*512,driver['blocks']*512)).hexdigest())
        if hashes!=donor_details['driver_bytes_sha256']: raise ValueError('SCSI driver changed')
        checks.append('SCSI driver bytes preserved')
        result['driver_donor']=donor_details
    if expected_files is not None:
        actual={':'.join(f['path'].split(':')[1:]):f for f in result['files']}
        differences=[]; verified=0
        for name,expected in expected_files.items():
            got=actual.get(name)
            if got is None: raise ValueError('Missing file '+name)
            fields=['type','creator','data_size','resource_size','data_sha256','resource_sha256']
            changed=[k for k in fields if got[k]!=expected[k]]
            if changed:
                if expected['alias']: differences.append({'path':name,'alias_metadata_regenerated':changed})
                else: raise ValueError('File fork/metadata changed: '+name+' '+str(changed))
            else: verified+=1
        result['fork_preservation']={'verified_files':verified,'regenerated_aliases':differences}
        checks.append('input file forks and type/creator preserved (aliases separately recorded)')
    if bootable:
        blessed=u32(image.mdb,92)
        if blessed not in image.folders or image.boot[:2]!=b'LK': raise ValueError('Missing boot blocks/blessed folder')
        children=[x for x in image.files if x['parent']==blessed]
        if not any(x['type'].upper()=='ZSYS' for x in children) or not any(x['type']=='FNDR' for x in children):
            raise ValueError('Blessed folder lacks System/Finder')
        checks.append('boot signature and blessed System/Finder folder')
        result['bootable_structure']=True
    else:
        if u32(image.mdb,92)!=0: raise ValueError('Unexpected blessing on empty data image')
    image.close(); result['checks_passed']=checks
    return result

