use crate::{
    Block, Config, Error, ExtSymbol, ExtSymbolValue, Header, MemSegment, MemType, RelocData,
    Result, Symbol, from_longword32, usize_from_u32,
};
use std::io::Read;

/// Reader implementing `Iterator` which reads and returns blocks one by one from a hunk file.
///
/// The returned items are `Option<Result<Block>>`s. Errors are returned if there is
/// an error reading the stream or parsing the hunk format. `None` is returned when the stream ends.
///
/// # Examples
///
/// Low-level reading and writing of blocks:
///
/// ```no_run
/// let bufreader = std::io::BufReader::new(std::fs::File::open("test.lib")
///     .expect("can't open file"));
/// let mut breader = hunkfile::BlockReader::new(bufreader, hunkfile::Config::default())
///     .expect("hunk read error");
/// let mut buf = std::io::Cursor::new(vec![]);
/// let mut bwriter = hunkfile::BlockWriter::new(&mut buf, hunkfile::Config::default())
///     .expect("write error");
/// while let Some(h) = breader.next() {
///     match h {
///         Ok(b) => {
///             println!("block: {:?}", b);
///             bwriter.write_block(&b).expect("write error");
///         },
///         Err(e) => {
///             eprintln!("error: {:?}", e);
///             break;
///         }
///     }
/// }
/// ```
pub struct BlockReader<R> {
    /// Stream implementing Read, underlying reader.
    stream: R,
    /// Config.
    config: Config,
}

impl<R: Read> BlockReader<R> {
    /// Creates a new `BlockReader` to read blocks from `stream`.
    /// The given stream must implement the `Read` trait.
    pub fn new(stream: R, config: Config) -> Result<BlockReader<R>> {
        Ok(BlockReader { stream, config })
    }

    /// Returns the config used by this reader.
    pub fn config(&self) -> &Config {
        &self.config
    }

    /// Sets the config used by this reader.
    pub(crate) fn set_config(&mut self, config: Config) {
        self.config = config;
    }

    /// Consumes the `BlockReader` returning the wrapped reader.
    pub fn into_inner(self) -> R {
        self.stream
    }

    /// Gets a reference to the underlying reader.
    ///
    /// Care should be taken to avoid modifying the internal state of the underlying reader
    /// as doing so may move the stream position not to point to the next block.
    pub const fn get_ref(&self) -> &R {
        &self.stream
    }

    /// Gets a mutable reference to the underlying reader.
    ///
    /// Care should be taken to avoid modifying the internal state of the underlying reader
    /// as doing so may move the stream position not to point to the next block.
    pub fn get_mut(&mut self) -> &mut R {
        &mut self.stream
    }
}

impl<R: Read> Iterator for BlockReader<R> {
    type Item = Result<Block>;

    fn next(&mut self) -> Option<Self::Item> {
        let block = match read_block(&mut self.stream, &self.config) {
            Ok(Some(b)) => b,
            Ok(None) => {
                return None;
            }
            Err(e) => {
                return Some(Err(e));
            }
        };
        Some(Ok(block))
    }
}

fn read_block(stream: &mut dyn Read, config: &Config) -> Result<Option<Block>> {
