            relocs: read_relocs16(stream)?,
        },
        crate::BLOCK_TYPE_RELRELOC32 => Block::RelReloc32 {
            relocs: read_relocs32(stream)?,
        },
        crate::BLOCK_TYPE_ABSRELOC16 => Block::AbsReloc16 {
            relocs: read_relocs16(stream)?,
        },
        crate::BLOCK_ADVISORY_VALUE.. => {
            let data = read_bytes(stream).map_err(|e| match e {
                Error::SizeTooLarge(_) => Error::SizeTooLarge("invalid size for advisory block"),
                _ => e,
            })?;
            Block::Advisory {
                block_type: block_type & 0x1fff_ffff,
                data,
            }
        }
        _ => {
            return Err(Error::UnknownBlockType(block_type));
        }
    };
    Ok(Some(block))
}

fn read_mem_type(stream: &mut dyn Read, block_type: u32) -> Result<MemType> {
    match block_type & 0xc000_0000 {
        0x0000_0000 => Ok(MemType::Any),
        0x4000_0000 => Ok(MemType::Chip),
        0x8000_0000 => Ok(MemType::Fast),
        _ => Ok(MemType::Custom(read_u32(stream)?)),
    }
}

fn read_header(stream: &mut dyn Read) -> Result<Header> {
    // read library names, the last name has a zero length (empty string)
    let mut resident_libraries = vec![];
    loop {
        let libname = read_string(stream)?;
        if libname.is_empty() {
            break;
        }
        resident_libraries.push(libname);
    }
    let number_of_segments = read_u32(stream)?;
    let first_loadable = read_u32(stream)?;
    let last_loadable = read_u32(stream)?;
    if last_loadable < first_loadable {
        return Err(Error::InvalidValue(
            "header has last loadable value less than first loadable value",
            u64::from(first_loadable),
        ));
    }
    // read hunk sizes
    let mut mem_segments = vec![];
    for _ in 0..(last_loadable - first_loadable + 1) {
        let memtype_and_size = read_u32(stream)?;
        let byte_size = from_longword32(memtype_and_size & 0x1fff_ffff)?;
        let mem_type = match memtype_and_size & 0xc000_0000 {
            0x4000_0000 => MemType::Chip,
            0x8000_0000 => MemType::Fast,
            0xc000_0000 => {
                let flags = read_u32(stream)? & 0xbfff_ffff;
                MemType::Custom(flags)
            }
            _ => MemType::Any,
        };
        mem_segments.push(MemSegment {
            mem_type,
            byte_size,
        });
    }
    Ok(Header {
        resident_libraries,
        number_of_segments,
        first_loadable,
        last_loadable,
        mem_segments,
    })
}

fn read_relocs32(stream: &mut dyn Read) -> Result<Vec<RelocData>> {
    let mut relocs = vec![];
    loop {
        let offset_count = read_u32(stream)?;
        if offset_count == 0 {
            break;
        }
        let hunk_number = read_u32(stream)?;
        let mut offsets = vec![];
        for _ in 0..offset_count {
            let offset = read_u32(stream)?;
            offsets.push(offset);
        }
        relocs.push(RelocData {
            hunk_number,
            offsets,
        });
    }
    Ok(relocs)
}

fn read_relocs16(stream: &mut dyn Read) -> Result<Vec<RelocData>> {
    let mut relocs = vec![];
    let mut bytes_read = 0u32;
    loop {
        let offset_count = read_u16(stream)?;
        bytes_read += 2;
        if offset_count == 0 {
            break;
        }
        let hunk_number = u32::from(read_u16(stream)?);
        bytes_read += 2;
        let mut offsets = vec![];
        for _ in 0..offset_count {
            let offset = read_u16(stream)?;
            bytes_read += 2;
            offsets.push(u32::from(offset));
        }
        relocs.push(RelocData {
            hunk_number,
            offsets,
        });
    }
    // ensure that the next read is at the longword boundary
    if bytes_read & 3 != 0 {
        read_u16(stream)?;
    }
    Ok(relocs)
}

fn read_symbol_ref_offsets(stream: &mut dyn Read) -> Result<Vec<u32>> {
    let count = read_u32(stream)?;
    let mut refs = vec![];
    for _ in 0..count {
        refs.push(read_u32(stream)?);
    }
    Ok(refs)
}

fn read_u8(stream: &mut dyn Read) -> Result<u8> {
    let mut data = [0u8; 1];
    stream.read_exact(&mut data)?;
    Ok(data[0])
}

fn read_u16(stream: &mut dyn Read) -> Result<u16> {
    let mut data = [0u8; 2];
    stream.read_exact(&mut data)?;
    Ok(u16::from_be_bytes(data))
}

fn read_u32(stream: &mut dyn Read) -> Result<u32> {
    let mut data = [0u8; 4];
    stream.read_exact(&mut data)?;
    Ok(u32::from_be_bytes(data))
}

fn read_bytes(stream: &mut dyn Read) -> Result<Vec<u8>> {
    // length in longwords (4 bytes)
    let len = read_u32(stream)?;
    if len == 0 {
        return Ok(Vec::new());
    }
    let byte_len =
        from_longword32(len).map_err(|_| Error::SizeTooLarge("invalid size for byte data"))?;
    let mut s = vec![0u8; usize_from_u32(byte_len)?];
    stream.read_exact(&mut s)?;
    Ok(s)
}

fn read_string_with_len(stream: &mut dyn Read, byte_len: u32) -> Result<String> {
    if byte_len == 0 {
        return Ok(String::new());
    }
    let mut s = vec![0u8; usize_from_u32(byte_len)?];
    stream.read_exact(&mut s)?;
    // remove the null-terminator and any data after it
    for (i, b) in s.iter().enumerate() {
        if *b == 0 {
            s.truncate(i);
            break;
        }
    }
    Ok(crate::convert_latin1_to_string(&s))
}

fn read_string(stream: &mut dyn Read) -> Result<String> {
    // length in longwords (4 bytes)
    let len = read_u32(stream)?;
    let byte_len =
        from_longword32(len).map_err(|_| Error::SizeTooLarge("invalid size for a string"))?;
    read_string_with_len(stream, byte_len)
}

