#include <stdio.h>
#include <stdlib.h>

unsigned read4(FILE * f) {
	static unsigned char b[4];
	if (fread(b, 4, 1, f) != 1)
		return 0xffffffff;
	return (b[0] << 24) | (b[1] << 16) | (b[2] << 8) | b[3];
}

unsigned read2(FILE * f) {
	static unsigned char b[2];
	if (fread(b, 2, 1, f) != 1)
		return 0xffffffff;
	return (b[0] << 8) | b[1];
}

unsigned nameLen; // size of current name
char * name;    // some name

void readName(unsigned l, FILE * f) {
	if (nameLen < l) {
		free(name);
