    def __str__(self):
        if self.type:
            return (f"{self.name:12} {self.type:9} LOAD=&{self.load_address:04X} "
                f"EXEC=&{self.exec_address:04X} {self.length:6} bytes")
        else:
            return f"{self.name:12} NOHEADERS {len(self.data)} bytes"

    def decode(self) -> str:
        if self.type == "BASIC":
            return detokenise_basic(self.data)
        if self.type == "BINARY":
            return disassemble_z80(self.data, self.load_address)
        raise ValueError(f"Unsupported file type: {self.type}")

    def write(self, outdir: Path, raw: bool = False):
        output = outdir / self.name
        if raw:
            output.write_bytes(self.data)
        else:
            output.write_text(self.decode(), encoding="utf-8")


@dataclass
class DSK:
    path: Path
    files: list[CPCFile] = field(default_factory=list)

    def get_file(self, name: str) -> CPCFile:
        for file in self.files:
            if file.name.upper() == name.upper():
                return file

        raise KeyError(f"{name}: file not found")


def u16le(b, off):
    return b[off] | (b[off + 1] << 8)


def parse_dsk(path: Path) -> DSK:
    raw = path.read_bytes()

    if not raw.startswith(b"MV - CPCEMU"):
        raise ValueError("Pas un DSK CPCEMU standard")

    tracks = raw[0x30]
    sides = raw[0x31]
    track_size = u16le(raw, 0x32)

    #print(f"DSK: {tracks} tracks, {sides} side(s), track_size={track_size} octets")

    disk = bytearray()
    off = 0x100

    for _ in range(tracks * sides):
        th = raw[off:off + 0x100]
        if not th.startswith(b"Track-Info"):
            raise ValueError(f"Track header invalid: 0x{off:x}")
        nsectors = th[0x15]
        sector_data_off = off + 0x100
        sectors = []

        for i in range(nsectors):
            sd = th[0x18 + i * 8:0x20 + i * 8]
            sector_id = sd[2]
            n = sd[3]
            sector_size = 128 << n
            payload = raw[sector_data_off:sector_data_off + sector_size]
            sectors.append((sector_id, payload))
            sector_data_off += sector_size

        for _, payload in sorted(sectors):
            disk.extend(payload)

        off += track_size

    directory = disk[:DIR_SIZE]
    files = defaultdict(list)

    for off in range(0, DIR_SIZE, 32):
        e = directory[off:off + 32]
        user = e[0]
        if user == 0xE5 or user > 15:
            continue
        name = bytes(c & 0x7F for c in e[1:9]).decode("ascii").rstrip()
        ext = bytes(c & 0x7F for c in e[9:12]).decode("ascii").rstrip()
        filename = name
        if ext:
            filename += "." + ext
        extent = e[12]
        records = e[15]
        blocks = [b for b in e[16:32] if b != 0]
        files[filename].append((extent, records, blocks))

    extracted = DSK(path)


    for filename, extents in files.items():
        content = bytearray()
        for extent, records, blocks in sorted(extents):
            extent_data = bytearray()
            for block in blocks:
                start = block * BLOCK_SIZE
                extent_data.extend(disk[start:start + BLOCK_SIZE])
            content.extend(extent_data[:records * 128])
        b_content = bytes(content)
        info = amsdos_info(b_content)
        if info:
            extracted.files.append(
                CPCFile(
                    filename,
                    b_content[128:128 + info["length"]],
                    info["type"],
                    info["length"],
                    info["load"],
                    info["exec"]))
        else:
            extracted.files.append(CPCFile(filename, b_content))

    return extracted


def amsdos_info(raw):
    if len(raw) < AMSDOS_HEADER_SIZE:
        return None

    expected = u16le(raw, 0x43)

    actual = sum(raw[:0x43]) & 0xFFFF

    if actual != expected:
        return None

    ftype = raw[0x12]

    load = u16le(raw, 0x15)
    length = u16le(raw, 0x18)
    exec_addr = u16le(raw, 0x1A)

    return {
        "type": FILE_TYPES.get(ftype, str(ftype)),
        "load": load,
        "length": length,
        "exec": exec_addr,
    }
